const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const source=fs.readFileSync('scripts/check-npm-audit.mjs','utf8');
const executable=source.replace(/^#!.*\n/,'').replace("import { spawnSync } from 'node:child_process';",'');
const report=(name,severity='high',via=[])=>({metadata:{vulnerabilities:{high:severity==='high'?1:0,critical:severity==='critical'?1:0}},vulnerabilities:name?{[name]:{severity,via}}:{}});
const cases=[['clean',report(null),0],['retained-baseline',report('postcss','high',[{source:1124252,severity:'high'}]),0],['removed-adm-zip',report('adm-zip'),1],['removed-onnxruntime-node',report('onnxruntime-node'),1],['removed-advisory-1123686',report('postcss','high',[{source:1123686,severity:'high'}]),1],['removed-advisory-1239030',report('postcss','high',[{source:1239030,severity:'high'}]),1],['critical-still-blocked',report('anything','critical'),1],['expiry-still-blocked',report(null),1,'2026-10-21'],['actual-remaining-findings',JSON.parse(fs.readFileSync('<tmp>/alice-admzip-audit-after.json')),1]];
const rows=[];
for(const [name,data,expected,date='2026-10-04'] of cases){let exit=0;const signal={};const logs=[];const context={spawnSync:(cmd,args)=>{assert.equal(cmd,'npm');assert.deepEqual(Array.from(args),['audit','--json']);return {stdout:JSON.stringify(data),stderr:'',status:0}},process:{exit:n=>{exit=n;throw signal}},Date:class extends Date{constructor(){super(date+'T12:00:00Z')}},console:{log:x=>logs.push(x),error:x=>logs.push(x)}};try{vm.runInNewContext(executable,context,{timeout:1000})}catch(e){if(e!==signal)throw e}assert.equal(exit,expected,name);rows.push({name,expected,actual:exit,passed:true,logs});}
fs.writeFileSync('<tmp>/alice-admzip-policy-checks.json',JSON.stringify({methodology:'Actual audit-script logic executed in VM with npm JSON and clock stubs. Only shebang/import removed; no network. Does not replace the real npm audit/gate invocation.',sourceSha256:crypto.createHash('sha256').update(source).digest('hex'),cases:rows},null,2)+'\n');console.log('9 audit policy checks passed');
